/*
 * A039745  Diameter of symmetric group S_n when generated by (1,2) and
 *          (1,2,3,...,n).
 * https://oeis.org/A039745
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  hard, nonn, nice, more
 * Formula:   a(1)=0, a(2)=1, a(3)=2, a(4)=6, a(5)=11,
 *            a(n)=a(n-1)+3*floor(n/2)-2 for n ≥ 6 (This recurrence follows
 *            from the known diameter of the directed Cayley graph of S_n
 *            generated by (1,2) and the n‑cycle.)
 * Range:     u8 n <= 15, u16 n <= 15, u32 n <= 15, u64 n <= 15, u128 n <= 15,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 1) return 0;
    if (n == 2) return 1;
    if (n == 3) return 2;
    if (n == 4) return 6;
    if (n == 5) return 11;

    seq_t res = 11;                /* a(5) */
    for (idx_t k = 6; k <= n; ++k) {
        seq_t inc = (seq_t)3 * (seq_t)(k / 2) - 2;
        res += inc;
    }
    return res;
}
